content.content:
package app

import (
	"log"
	"sort"
	"strings"

	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/command"
	"github.com/anthnel/devdesk/internal/config"
	"github.com/anthnel/devdesk/internal/contextcmd"
	"github.com/anthnel/devdesk/internal/ui/components"
)

const (
	noteNewContext      = "Create a context"
	notePreviousContext = "Previous context"
	wordNewContext      = "new"
	wordPreviousContext = "-"
)

// contextNamesLoadedMsg carries the context names read off disk when the
// command line opened.
type contextNamesLoadedMsg struct {
	Names []string
	Err   error
}

// contextArgs is the in-memory snapshot behind the context argument provider.
// Only Update() writes it (Rule 110); SuggestArgs never touches the disk.
type contextArgs struct {
	names             []string
	ready             bool
	current, previous string
}

// SuggestArgs implements command.ArgProvider from the snapshot only.
func (c *contextArgs) SuggestArgs(prefix string) ([]command.ArgSuggestion, bool) {
	if !c.ready {
		return nil, false
	}
	// The suggester trims trailing whitespace, so "new " reaches us as "new":
	// once the word is typed there is nothing left to complete.
	if p := strings.ToLower(prefix); p == wordNewContext || strings.HasPrefix(p, wordNewContext+" ") {
		return nil, true
	}
	var out []command.ArgSuggestion
	for _, n := range contextcmd.Match(prefix, c.names) {
		out = append(out, command.ArgSuggestion{Value: n, Current: n == c.current})
	}
	for _, s := range []command.ArgSuggestion{
		{Value: wordPreviousContext, Note: notePreviousContext},
		{Value: wordNewContext, Note: noteNewContext},
	} {
		if strings.HasPrefix(s.Value, strings.ToLower(prefix)) {
			out = append(out, s)
		}
	}
	return out, true
}

// loadContextNamesCmd lists the contexts off the Update goroutine.
func loadContextNamesCmd() tea.Cmd {
	return func() tea.Msg {
		names, err := config.ListContexts()
		sort.Strings(names)
		return contextNamesLoadedMsg{Names: names, Err: err}
	}
}

// handleContextNamesLoaded stores the names read when the command line opened.
func (a *App) handleContextNamesLoaded(msg contextNamesLoadedMsg) (tea.Model, tea.Cmd) {
	if msg.Err != nil {
		log.Printf("ERROR [app/context] list contexts: %v", msg.Err)
		a.ctxArgs.ready = false
		return a, components.PostFooter(components.LevelError, "Failed to list contexts — check logs")
	}
	a.ctxArgs.names, a.ctxArgs.ready = msg.Names, true
	a.ctxArgs.current, a.ctxArgs.previous = a.currentContext, a.previousContext
	if a.commandMode {
		a.refreshSuggestions()
	}
	return a, nil
}

// snapshot returns the contexts known to the router.
func (a *App) snapshot() contextcmd.Snapshot {
	return contextcmd.Snapshot{
		Names:    a.ctxArgs.names,
		Current:  a.currentContext,
		Previous: a.previousContext,
		Ready:    a.ctxArgs.ready,
	}
}
package app

import (
	"errors"
	"slices"
	"testing"

	"github.com/anthnel/devdesk/internal/command"
	"github.com/anthnel/devdesk/internal/config"
	"github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/testutil"
)

// contextRouter builds a router through newWithSize (which registers the
// providers) over an isolated HOME holding the contexts default, work, wip.
func contextRouter(t *testing.T) *App {
	t.Helper()
	isolateHome(t)
	for _, name := range []string{"default", "work", "wip"} {
		if err := config.SaveContext(testConfig(), name); err != nil {
			t.Fatalf("SaveContext(%q): %v", name, err)
		}
	}
	a := newWithSize(testConfig(), 120, 40)
	a.currentContext = "work"
	return a
}

// loadContexts opens the command line and applies the load it started.
func loadContexts(t *testing.T, a *App) {
	t.Helper()
	cmd := a.enterCommandMode()
	msg, ok := testutil.MsgOf[contextNamesLoadedMsg](cmd)
	if !ok {
		t.Fatal("enterCommandMode produced no contextNamesLoadedMsg")
	}
	a.Update(msg)
}

func typeLine(a *App, text string) command.Suggestions {
	a.commandInput.SetValue(text)
	a.refreshSuggestions()
	return a.suggestions
}

func values(args []command.ArgSuggestion) []string {
	out := make([]string, len(args))
	for i, x := range args {
		out[i] = x.Value
	}
	return out
}

func TestContextOpeningCommandLineLoadsSortedNames(t *testing.T) {
	a := contextRouter(t)
	msg, ok := testutil.MsgOf[contextNamesLoadedMsg](a.enterCommandMode())
	if !ok {
		t.Fatal("no contextNamesLoadedMsg from enterCommandMode")
	}
	if msg.Err != nil {
		t.Fatalf("unexpected error: %v", msg.Err)
	}
	if want := []string{"default", "wip", "work"}; !slices.Equal(msg.Names, want) {
		t.Errorf("names = %v, want sorted %v", msg.Names, want)
	}
}

func TestContextArgsNotReadyBeforeLoad(t *testing.T) {
	a := contextRouter(t)
	s := typeLine(a, "ctx ")
	if s.ArgsReady || len(s.Args) != 0 {
		t.Errorf("before load: ready=%v args=%v, want not ready and none", s.ArgsReady, s.Args)
	}
	if a.snapshot().Ready {
		t.Error("snapshot is ready before any load")
	}
}

func TestContextArgsListOrderAndCurrent(t *testing.T) {
	a := contextRouter(t)
	loadContexts(t, a)
	s := typeLine(a, "ctx ")
	if !s.ArgsReady {
		t.Fatal("args not ready after load")
	}
	if got, want := values(s.Args), []string{"default", "wip", "work", "-", "new"}; !slices.Equal(got, want) {
		t.Fatalf("args = %v, want %v", got, want)
	}
	notes := map[string]string{}
	for _, x := range s.Args {
		notes[x.Value] = x.Note
		if x.Current != (x.Value == "work") {
			t.Errorf("%q: Current = %v, want only work to be current", x.Value, x.Current)
		}
	}
	if notes["work"] != "" || notes["default"] != "" || notes["wip"] != "" {
		t.Errorf("no context carries a note (the renderer labels the current one), got %v", notes)
	}
	if notes["-"] != "Previous context" || notes["new"] != "Create a context" {
		t.Errorf("notes for - and new = %q, %q", notes["-"], notes["new"])
	}
}

func TestContextArgsPrefixFiltersCaseInsensitively(t *testing.T) {
	a := contextRouter(t)
	loadContexts(t, a)
	s := typeLine(a, "ctx WO")
	if got, want := values(s.Args), []string{"work"}; !slices.Equal(got, want) {
		t.Errorf("prefix WO = %v, want %v", got, want)
	}
	s = typeLine(a, "ctx n")
	if got, want := values(s.Args), []string{"new"}; !slices.Equal(got, want) {
		t.Errorf("prefix n = %v, want %v", got, want)
	}
}

func TestContextArgsAfterNewListNothing(t *testing.T) {
	a := contextRouter(t)
	loadContexts(t, a)
	for _, line := range []string{"ctx new ", "ctx new fo"} {
		if s := typeLine(a, line); len(s.Args) != 0 {
			t.Errorf("%q gave %v, want no line", line, values(s.Args))
		}
	}
}

func TestContextSnapshotAfterLoad(t *testing.T) {
	a := contextRouter(t)
	loadContexts(t, a)
	snap := a.snapshot()
	if !snap.Ready || snap.Current != "work" || !slices.Equal(snap.Names, []string{"default", "wip", "work"}) {
		t.Errorf("snapshot = %+v", snap)
	}
}

func TestContextLoadErrorPostsFooterAndStaysNotReady(t *testing.T) {
	a := contextRouter(t)
